/**
 * The Wilderness
 * --------------
 * David hides in the wilderness of En Gedi, and when Saul comes to relieve himself in a cave, David cuts off the hem of his robe and refuses to strike. Stage: a sun-baked cliff with dark cave mouths, sheep, a hidden figure watching the king pass; craggy grey-gold rock, shimmering heat.
 *
 * Palette 0x241810 → 0x100a04 · light: storm · hero: sheep
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./david-kit.js.
 */

import { THREE, createScene, column, throne, sheep, person } from './david-kit.js';

const BG = 0x241810;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 3103272957, bg: BG, fogNear: 40, fogFar: 160 });

    /* light — storm */
    W.lights({ sky: 0x4a5a6c, gnd: 0x2a3238, hemi: 0.55, sun: 0xa8bcc8, sunI: 0.6, sunPos: [-30, 40, 20] });

    const clouds = W.grp(group, [0, 0, 0], { name: 'storm_clouds' });
    [[-50, 36, -110, 34], [0, 44, -130, 40], [55, 38, -115, 30], [-95, 40, -120, 28]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0x2a3238, { opacity: 0.9 }), [x, y, z], { s: [s, s * 0.3, s * 0.6] });
    });
    W.backdrop(clouds);
    W.point(0xbfd4f0, 4.0, 220, 25, 30, -40, 0.85);  // lightning flicker

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* palace: columns, banners and the throne */
    for (let i = -2; i <= 2; i++) column(W, group, i * 8, 0, -30, 11, 1.3, 0x110b04, { band: 0x1b120c });
    throne(W, group, 0, 0, -24, 1.4, { gold: 0x17100a });

    /* hero: the sheep */
    sheep(W, group, 0, 0, 0, 0, 1.3);
    W.disc([0, 4, -10], 4, 0x2f1f15, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, bend: 0.02, ry: -0.60, s: 1.12 });
    person(W, group, [4.5, 0, 6], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, bend: 0.02, ry: 0.46, s: 1.18 });
    person(W, group, [1, 0, -5], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, bend: 0.02, ry: -0.41, s: 1.13 });

    return W.finish();
}

export default { build };
